<?php if(!defined('PRIVATEMAIL_SETTINGS_VIEW')){http_response_code(404);exit;}?>
<section class="card" id="domainEditor"><div class="card-title"><span class="card-icon"><?=layoutIcon('at')?></span><div><h2>Domains</h2><p>Choose which domains are available for new aliases.</p></div></div>
<p class="field-hint">DNS and catch-all routing must already deliver to the chosen mailbox. This changes PrivateMail’s domain list only.</p>
<form method="post" class="settings-form"><?php settingsHidden('domain_save');?><input type="hidden" name="domain_id" value="<?=$domainRow?(int)$domainRow['id']:0?>"><label class="settings-label">Domain<input name="domain" placeholder="example.com" value="<?=Security::e((string)($domainRow['domain']??''))?>" required></label>
<label class="settings-label">Receiving mailbox<select name="domain_account" required><option value="">Choose mailbox</option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=$domainRow&&(int)$domainRow['account_id']===(int)$a['id']?'selected':''?>><?=Security::e($a['name'])?></option><?php endforeach;?></select></label>
<label class="domain-active"><input type="checkbox" name="domain_active" <?=!$domainRow||(int)$domainRow['active']===1?'checked':''?>> Active for alias creation</label><div class="connection-actions"><?php if($domainRow):?><a class="button" href="/settings.php#domainEditor">Cancel edit</a><?php endif;?><button class="button primary"><?=$domainRow?'Update domain':'Add domain'?></button></div></form>
<div class="managed-list"><?php foreach($managedDomains as $d):?><article class="managed-row domain-row"><div><strong><?=Security::e($d['domain'])?></strong><small><?=Security::e((string)($d['account_name']??'Choose a mailbox'))?> · <?=(int)$d['active']===1?'Active':'Inactive'?></small></div><a class="button" aria-label="Edit <?=Security::e($d['domain'])?>" href="/settings.php?domain_edit=<?=(int)$d['id']?>#domainEditor"><?=layoutIcon('settings')?></a><details class="remove-confirm"><summary>Remove</summary><form method="post" data-confirmation><?php settingsHidden('domain_remove');?><input type="hidden" name="domain_id" value="<?=(int)$d['id']?>"><p class="field-hint">Existing aliases and received mail will be kept.</p><button type="button" class="confirmation-cancel" data-confirm-cancel data-confirm-close>Cancel</button><button class="button danger-action" data-confirm-danger>Remove domain</button></form></details></article><?php endforeach;?></div>
</section>
